//keyisDown( keyCode )

function setup() {
  createCanvas(windowWidth, windowHeight);
}

function draw() {
  background(220);
  //checkMulti()
}

function checkMulti(){
  //check for multiple key presses 3 ( simotanious)
  strokeWeight(mouseX/10)
  stroke(255,0,0)
  let a = keyIsDown(65); //"a"
  let b = keyIsDown(66); //"b"
  let c = keyIsDown(67); //"c"
  textSize(40);
  text("a: " + a + "\tb:" + b +"\tc:" + c, 100, 300);
}

